SELECT x7.v42064, x7.v42064, ST_WITHIN(ST_GEOMFROMTEXT('MULTIPOINT(4 4,5 5)'), ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(POLYGON((0 0,0 10,10 10,10 0,0 0),(4 4,4 6,6 6,6 4,4 4)),POLYGON((4 4,4 6,6 6,6 4,4 4)))')) AS x3, x7.v42064 FROM v42063 AS x7 WHERE x7.v42064 > 1 AND x7.v42064 < 3 AND (x7.v42064 = 1 OR x7.v42064 = 2)